from pathlib import Path

import pytest

from travel_agent.training.export import (
    convert_command,
    from_lines,
    quantize_command,
    swap_model_from,
)

BASE = r"C:\Users\u\.ollama\models\blobs\sha256-aaaa"
PROJECTOR = r"C:\Users\u\.ollama\models\blobs\sha256-bbbb"
MODELFILE = (
    '# Modelfile generated by "ollama show"\n'
    "# To build a new Modelfile based on this, replace FROM with:\n"
    "# FROM qwen3.5:4b\n"
    "\n"
    f"FROM {BASE}\n"
    f"FROM {PROJECTOR}\n"
    "RENDERER qwen3.5\n"
    "PARSER qwen3.5\n"
    "PARAMETER presence_penalty 1.5\n"
    "PARAMETER temperature 1\n"
    'LICENSE """Apache License\n'
    "FROM is just a word inside the license text\n"
    '"""\n'
)


def test_swap_replaces_only_the_text_weights_line() -> None:
    new = Path(r"C:\dev\travelagent-runs\sft\sft-v1\model-Q4_K_M.gguf")
    out = swap_model_from(MODELFILE, BASE, new)
    assert from_lines(out) == [str(new), PROJECTOR]
    before = [line for line in MODELFILE.splitlines() if line != f"FROM {BASE}"]
    after = [line for line in out.splitlines() if line != f"FROM {new}"]
    assert before == after


def test_swap_refuses_a_missing_or_ambiguous_line() -> None:
    with pytest.raises(ValueError):
        swap_model_from(MODELFILE, r"C:\khong-co", Path("x.gguf"))
    with pytest.raises(ValueError):
        swap_model_from(MODELFILE + f"FROM {BASE}\n", BASE, Path("x.gguf"))


def test_swap_keeps_windows_line_endings() -> None:
    crlf = MODELFILE.replace("\n", "\r\n")
    out = swap_model_from(crlf, BASE, Path("m.gguf"))
    assert "FROM m.gguf\r\n" in out
    assert out.count("\r\n") == crlf.count("\r\n")


def test_commands_point_at_llama_cpp_tools() -> None:
    llama = Path(r"C:\dev\llama.cpp")
    convert = convert_command(Path("py.exe"), llama, Path("merged"), Path("m.gguf"))
    assert convert[1].endswith("convert_hf_to_gguf.py")
    assert convert[-2:] == ["--outtype", "bf16"]
    quantize = quantize_command(llama, Path("m.gguf"), Path("q.gguf"), "Q4_K_M")
    assert quantize[0].endswith("llama-quantize.exe")
    assert quantize[1:] == ["m.gguf", "q.gguf", "Q4_K_M"]
